import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.76ZGnlPi.js";const u=JSON.parse('{"title":"Reseller Commission Guide","description":"","frontmatter":{},"headers":[],"relativePath":"customer/reseller-commission/index.md","filePath":"customer/reseller-commission/index.md"}'),o={name:"customer/reseller-commission/index.md"};function n(r,t,d,h,l,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="reseller-commission-guide" tabindex="-1">Reseller Commission Guide <a class="header-anchor" href="#reseller-commission-guide" aria-label="Permalink to &quot;Reseller Commission Guide&quot;">​</a></h1><p>For partners holding the <strong><code>RESELLER</code></strong> pricing tier. It covers what a reseller earns, when the money becomes withdrawable, and how a payout is requested.</p><blockquote><p><strong>A reseller pays silver prices.</strong> The <code>RESELLER</code> tier is priced <strong>identically to <code>SILVER</code></strong> — same search prices, same booking limits. What the tier adds is a commission (cashback) per seated passenger, paid separately from the booking. Nothing in the price response distinguishes the two tiers; see <a href="/ahlaan-train-docs/customer/custom-ota/">Custom OTA → <code>promoTierPrices</code></a> for the one place that matters to a price consumer.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Who earns</strong></td><td>The <strong>organization</strong>, when the booking has one; an organization-less partner earns on their own user row.</td></tr><tr><td><strong>Which bookings</strong></td><td><strong>Custom bookings only</strong> — the tier-priced flow. Regular OTA bookings earn nothing.</td></tr><tr><td><strong>How much</strong></td><td>A fixed SAR amount <strong>per seated passenger</strong>: one for adults, one for children. <strong>Infants earn nothing.</strong> Defaults are 5 SAR and 5 SAR; the live figures are set by an admin.</td></tr><tr><td><strong>Currency</strong></td><td><strong>SAR</strong> is canonical. Every amount on these endpoints is SAR.</td></tr><tr><td><strong>Bank fee</strong></td><td>Absorbed by Ahlaan. The partner receives the full commission.</td></tr></tbody></table><h3 id="which-bookings-count" tabindex="-1">Which bookings count <a class="header-anchor" href="#which-bookings-count" aria-label="Permalink to &quot;Which bookings count&quot;">​</a></h3><p>A booking earns commission when the <strong>resolved effective pricing tier recorded on it at booking time</strong> was <code>RESELLER</code>. That is a frozen record, not a re-read of the account&#39;s tier today, which has two consequences worth knowing:</p><ul><li>Bookings made <strong>before</strong> the tier was granted earn nothing. There is no backfill.</li><li>Being priced as a reseller is what counts. A caller whose promo access is switched off is priced as a holder, and a booking made that way carries no reseller tier and so earns nothing.</li></ul><hr><h2 id="the-two-stages" tabindex="-1">The two stages <a class="header-anchor" href="#the-two-stages" aria-label="Permalink to &quot;The two stages&quot;">​</a></h2><p>A commission row is written in two steps, and only the second one is money you can ask for.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>customer&#39;s money arrives  -&gt;  ESTIMATED   (accrued, NOT payable)</span></span>
<span class="line"><span>booking closed (COMPLETED) -&gt;  CONFIRMED  (payable)</span></span>
<span class="line"><span>claimed into a payout      -&gt;  payoutId set, still CONFIRMED</span></span>
<span class="line"><span>transfer recorded          -&gt;  paidAt set</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ESTIMATED</code></td><td>The invoice was paid. The figure is a projection from the passengers <strong>booked</strong>. It is shown to you, and it is <strong>not withdrawable</strong>.</td></tr><tr><td><code>CONFIRMED</code></td><td>The booking was closed. This is the withdrawable figure.</td></tr><tr><td><code>VOID</code></td><td>The booking was cancelled before the commission was paid. Nothing is owed.</td></tr></tbody></table><h3 id="why-the-confirmed-figure-can-be-lower" tabindex="-1">Why the confirmed figure can be lower <a class="header-anchor" href="#why-the-confirmed-figure-can-be-lower" aria-label="Permalink to &quot;Why the confirmed figure can be lower&quot;">​</a></h3><p>The estimate prices every booked passenger. The confirmed figure prices the passengers whose <strong>tickets were actually delivered</strong>. When the ticket source under-delivers, the difference is deducted and both figures stay on the row:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>estimatedPaxCount</code> / <code>estimatedAmountSAR</code></td><td>What the booking was expected to earn.</td></tr><tr><td><code>confirmedPaxCount</code> / <code>confirmedAmountSAR</code></td><td>What it actually earned.</td></tr><tr><td><code>unticketedPaxCount</code></td><td>Seats that were booked and not ticketed.</td></tr></tbody></table><p>Each un-ticketed seat is deducted at the <strong>adult</strong> amount. The ticketed count is a single total with no adult/child breakdown, so there is nothing to tell the system which of the missing seats was a child. While the two configured amounts are equal — as they are by default — the deduction is exact either way.</p><p><strong>Tickets that arrive late are still paid.</strong> If the missing tickets are uploaded after the booking was closed, a <strong>second commission row</strong> is written automatically for the recovered seats, already <code>CONFIRMED</code>. It is priced at the same per-passenger amount as the original row, so a late delivery restores exactly what the shortfall deducted.</p><hr><h2 id="who-may-see-the-figures-and-request-a-payout" tabindex="-1">Who may see the figures and request a payout <a class="header-anchor" href="#who-may-see-the-figures-and-request-a-payout" aria-label="Permalink to &quot;Who may see the figures and request a payout&quot;">​</a></h2><p><strong>One account per organization</strong> — the account that registered the partnership, i.e. the user on the organization&#39;s mitra registration.</p><p>This is deliberately narrower than &quot;any member&quot;. Requesting a payout is where the destination bank account is typed, so widening the read would also widen who can direct the organization&#39;s money.</p><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>You are the organization&#39;s registered account</td><td>Full access to these endpoints.</td></tr><tr><td>You are another member of that organization</td><td><code>403</code></td></tr><tr><td>Your organization has <strong>no</strong> mitra registration</td><td><code>403</code>, naming the gap. An admin can still pay the partnership out.</td></tr><tr><td>You have no organization and hold the tier yourself</td><td>Full access to your own rows.</td></tr></tbody></table><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>All require a customer bearer token.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/v1/reseller-commissions</code></td><td>GET</td><td>Your commission rows, newest first</td></tr><tr><td><code>/api/v1/reseller-commissions/summary</code></td><td>GET</td><td>The three totals plus the payout minimum</td></tr><tr><td><code>/api/v1/reseller-commissions/payouts</code></td><td>GET</td><td>Your payouts, newest first</td></tr><tr><td><code>/api/v1/reseller-commissions/payouts</code></td><td>POST</td><td>Request a payout of everything available</td></tr><tr><td><code>/api/v1/reseller-commissions/payouts/:id/cancel</code></td><td>POST</td><td>Withdraw a payout request</td></tr></tbody></table><hr><h2 id="_1-commission-totals" tabindex="-1">1. Commission totals <a class="header-anchor" href="#_1-commission-totals" aria-label="Permalink to &quot;1. Commission totals&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api/v1/reseller-commissions/summary&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer &lt;token&gt;&#39;</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;estimatedSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;150.00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;availableSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;300.00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;paidSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1200.00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;minPayoutAmountSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.00&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>estimatedSAR</code></td><td>Accrued and <strong>not payable</strong>. The bookings behind it have not been closed, and the figure can come out lower.</td></tr><tr><td><code>availableSAR</code></td><td>Confirmed and not yet claimed into a payout. <strong>This is what a payout can draw on.</strong></td></tr><tr><td><code>paidSAR</code></td><td>Already transferred.</td></tr><tr><td><code>minPayoutAmountSAR</code></td><td>The smallest payout the system will send.</td></tr></tbody></table><blockquote><p><strong><code>0</code> is the absence of a floor, not a safe one.</strong> The value is returned even when it is <code>0</code> precisely so the screen shows what is in force rather than implying a rule that is not set. Display it.</p></blockquote><blockquote><p><strong>Money in an open payout request is in none of the three.</strong> Once a request claims your confirmed rows they leave <code>availableSAR</code>, and they only reach <code>paidSAR</code> when the transfer is recorded. Between those two moments the amount is on the payout itself — read <code>GET /payouts</code> to show it.</p></blockquote><h2 id="_2-list-commission-rows" tabindex="-1">2. List commission rows <a class="header-anchor" href="#_2-list-commission-rows" aria-label="Permalink to &quot;2. List commission rows&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api/v1/reseller-commissions?page=1&amp;limit=20&amp;status=CONFIRMED&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer &lt;token&gt;&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Query</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>page</code></td><td>no</td><td>Defaults to 1</td></tr><tr><td><code>limit</code></td><td>no</td><td>Defaults to 20, <strong>capped at 100</strong> server-side</td></tr><tr><td><code>status</code></td><td>no</td><td><code>ESTIMATED</code>, <code>CONFIRMED</code> or <code>VOID</code></td></tr></tbody></table><p>The response is <code>{ &quot;data&quot;: [...], &quot;meta&quot;: { &quot;total&quot;, &quot;page&quot;, &quot;limit&quot;, &quot;totalPages&quot; } }</code>. Each row carries the frozen per-passenger amounts it was priced at (<code>amountPerAdultSAR</code>, <code>amountPerChildSAR</code>), both legs described above, the booking it was earned on (<code>customBooking</code>: code, departure date, route, status), <code>payoutId</code> once claimed, and <code>paidAt</code> once transferred.</p><blockquote><p><strong>Money fields are JSON strings, not numbers</strong> (<code>&quot;25.00&quot;</code>). They are exact decimals; parse them as such rather than as floats.</p></blockquote><blockquote><p><strong>A booking can have more than one row.</strong> <code>sequence</code> distinguishes them — <code>1</code> is the original accrual, and a later sequence is a top-up for tickets that arrived after the close.</p></blockquote><h2 id="_3-request-a-payout" tabindex="-1">3. Request a payout <a class="header-anchor" href="#_3-request-a-payout" aria-label="Permalink to &quot;3. Request a payout&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api/v1/reseller-commissions/payouts&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer &lt;token&gt;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;destinationBankCode&quot;: &quot;BCA&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;destinationBankName&quot;: &quot;Bank Central Asia&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;destinationAccountNumber&quot;: &quot;1234567890&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;destinationAccountName&quot;: &quot;PT Mitra Reseller&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>This claims <strong>every</strong> confirmed, unpaid commission row you have into one payout, created as <code>REQUESTED</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Required to request</th><th>Required to be approved</th></tr></thead><tbody><tr><td><code>destinationBankCode</code></td><td>no</td><td>no</td></tr><tr><td><code>destinationBankName</code></td><td>no</td><td>no</td></tr><tr><td><code>destinationAccountNumber</code></td><td>no</td><td><strong>yes</strong></td></tr><tr><td><code>destinationAccountName</code></td><td>no</td><td><strong>yes</strong></td></tr></tbody></table><blockquote><p><strong>The destination is typed per payout — it is not a saved, verified account.</strong> Check it against your last payout (<code>GET /payouts</code>) before submitting: a typo sends the money to a stranger. An admin who did not request the payout has to approve the destination before anything is transferred, which is the reason a payout does not go straight to <code>APPROVED</code>. That approver can only accept or reject the account you typed — they cannot replace it — so what you send here is what the money goes to. Got it wrong? The payout is rejected and you request again with the right account.</p></blockquote><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>400</code></td><td>Nothing confirmed and unpaid is available, or the total is below <code>minPayoutAmountSAR</code>. The message names how much more must be confirmed first.</td></tr><tr><td><code>409</code></td><td>Another payout claimed part of the same commission while your request was in flight. <strong>Nothing was paid out</strong> — re-read the balance and retry.</td></tr></tbody></table><h2 id="_4-list-your-payouts" tabindex="-1">4. List your payouts <a class="header-anchor" href="#_4-list-your-payouts" aria-label="Permalink to &quot;4. List your payouts&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api/v1/reseller-commissions/payouts?page=1&amp;limit=20&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer &lt;token&gt;&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Payout status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>REQUESTED</code></td><td>Waiting for an admin to check the destination account. Still cancellable.</td></tr><tr><td><code>APPROVED</code></td><td>Destination checked. The transfer is being made.</td></tr><tr><td><code>PAID</code></td><td>Transferred. <code>reference</code> carries the bank reference and <code>paidAt</code> the timestamp.</td></tr><tr><td><code>REJECTED</code></td><td>Refused, with <code>rejectionReason</code>. The commission rows go back to available.</td></tr><tr><td><code>CANCELLED</code></td><td>Withdrawn by you. The commission rows go back to available.</td></tr></tbody></table><p><code>totalAmountSAR</code> is the canonical figure — what you were owed, in SAR. A payout sent in another currency also carries what actually left the bank (<code>payoutCurrency</code>, <code>payoutAmount</code>) and the rate it was converted at (<code>payoutRateToSAR</code>, SAR per one unit of that currency).</p><h2 id="_5-cancel-a-payout-request" tabindex="-1">5. Cancel a payout request <a class="header-anchor" href="#_5-cancel-a-payout-request" aria-label="Permalink to &quot;5. Cancel a payout request&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api/v1/reseller-commissions/payouts/&lt;payoutId&gt;/cancel&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer &lt;token&gt;&#39;</span></span></code></pre></div><p>Releases the claimed commission back to available. Allowed <strong>only while the payout is <code>REQUESTED</code></strong> — once a second person has approved the destination the transfer may already be in motion at the bank.</p><p>Somebody else&#39;s payout answers <code>404</code>, not <code>403</code>: confirming that the id exists would tell a stranger that money is waiting under it.</p><hr><h2 id="becoming-a-reseller" tabindex="-1">Becoming a reseller <a class="header-anchor" href="#becoming-a-reseller" aria-label="Permalink to &quot;Becoming a reseller&quot;">​</a></h2><p>The tier is chosen on the <a href="/ahlaan-train-docs/customer/mitra-registration/">mitra registration form</a> like <code>SILVER</code> and <code>GOLD</code>. Choosing it does not grant it: an admin confirms the <strong>refundable security deposit</strong> (10,000 SAR by default, and a promo can change what a given applicant is charged) and approves the registration first.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/customer/mitra-registration/">Mitra Registration</a> — applying for the tier</li><li><a href="/ahlaan-train-docs/customer/custom-booking/">Custom Booking</a> — the flow that earns commission</li><li><a href="/ahlaan-train-docs/customer/custom-booking-status/">Custom Booking Status</a> — what &quot;closed&quot; means</li></ul>`,61)])])}const g=e(o,[["render",n]]);export{u as __pageData,g as default};
